#[test]
fn golden_vectors_have_the_documented_shapes() {
    assert_eq!(PAN_CTX_IN.len(), 32);
    assert_eq!(PAN_CTX_OUT.len(), PAN_CTX_IN.len());
    assert_eq!(PAN_FRAMES_IN.len(), 24);
    assert_eq!(PAN_FRAMES_OUT.len(), PAN_FRAMES_IN.len());
    assert!(PAN_FRAMES_IN != PAN_FRAMES_OUT);
}
